INSERT INTO `allatok` (`webnev`, `nev`, `szarmazasi_hely`, `foosztaly`, `torzs`, `atlag_suly`, `atlag_eletkor`, `leiras`, `kep`, `kep_mime`, `atlag_meret`, `szerkeszto_id`) VALUES
('haromujju-lajhar', 'Háromujjú lajhár', 'Dél-Amerika', 'Négylábúak', 'Gerinchúrosok', '2-5 kg', '30-40 év', 'A háromujjú lajhár vagy más néven ai (Bradypus tridactylus) az emlősök (Mammalia) osztályának vendégízületesek (Xenarthra) öregrendjébe és a szőrös vendégízületesek (Pilosa) rendjébe, ezen belül a lajhárok (Folivora) alrendjébe és a háromujjú lajhárfélék (Bradypodidae) családjába tartozó faj.\r\nA háromujjú lajhár elterjedési területe Dél-Venezuela és Észak-Brazília közé esik.\r\nAz állat fej-törzs-hossza 40-75 centiméter, farokhossza 3-9 centiméter és testtömege 2,3-5,5 kilogramm. Bundája színe szürkésbarna. Karja szembetűnően hosszabb a lábánál; a faágon lógva karja segítségével hajtja előre magát. Mellső és hátsó végtagjain egyaránt három ujj található. Ujjait szőr borítja, és szervesen kapcsolódnak egymáshoz. Karmainak bőrszerűen megszarusodott belső fogófelülete biztonságot nyújt a kapaszkodásnál. Hallása és látása rossz, szaglószerve és tapintóérzéke fejlett.\r\nA háromujjú lajhár magányosan, a fák lombkoronájában él, és egyaránt éjjel-nappal aktív. Táplálékát a fák levelei alkotják. Az állat 30-40 évig él.', , 'image/jpeg', '40-75 centiméter', 6);
INSERT INTO `allatok` (`webnev`, `nev`, `szarmazasi_hely`, `foosztaly`, `torzs`, `atlag_suly`, `atlag_eletkor`, `leiras`, `kep`, `kep_mime`, `atlag_meret`, `szerkeszto_id`) VALUES
('hazi-macska', 'Házi Macska', 'Afrika', 'Négylábúak', 'Gerinchúrosok', '3-5 kg', '12-15 év', 'A macska, más néven házimacska (Felis silvestris catus) kisebb termetű húsevő emlős, ami a ragadozók rendjén belül a macskafélék (Felidae) családjának Felis neméhez és vadmacska (Felis silvestris) fajához tartozik. A vadmacska alfaja. Ügyes ragadozó, több mint 1000 faj tekinthető a zsákmányának. Ugyanakkor a kedvencként tartott háziállatok között más nemekkel keresztezett hibridjei is találhatók, ilyen például az itt felsorolt sziámi macska v. bengáli macska is. Emellett meglehetősen intelligens, beidomítható egyszerű parancsok végrehajtására vagy szerkezetek működtetésére – illetve képes önállóan is kisebb feladatok betanulására (lásd: A macska intelligenciája).\r\n\r\nKörülbelül 10 000 évvel ezelőtt kezdett az ember társaságában élni, háziasításának első ábrázolása mintegy 4000 éve Egyiptomban történt.', , 'image/jpeg', '40-50 cm', 5);
INSERT INTO `allatok` (`webnev`, `nev`, `szarmazasi_hely`, `foosztaly`, `torzs`, `atlag_suly`, `atlag_eletkor`, `leiras`, `kep`, `kep_mime`, `atlag_meret`, `szerkeszto_id`) VALUES
('oriaspanda', 'Óriáspanda', 'Sanhszi kínai tartományok ', 'Négylábúak', '	Gerinchúrosok', '70-125 kg', '25 év', 'Az óriáspanda elsősorban talajlakó, de jól mászik és úszik. Az óriás panda megroggyantott hátsó lábain is meg tud állni, de hamar elfárad, minden alkalmat kihasznál a pihenésre. Táplálékát legtöbbször ülve fogyasztja el, így mellső mancsa szabaddá válik, hogy a táplálékot megfogja. Ezek az állatok szürkületben vagy éjszaka aktívak, míg nappal fák üregeiben, sziklahasadékokban vagy barlangokban alszanak. A bambuszbozótban alagútszerű járatokat készít, hogy a táplálkozási területét alvóhelyével összekösse.', , 'image/jpeg', ' 150-190', 4);
INSERT INTO `allatok` (`webnev`, `nev`, `szarmazasi_hely`, `foosztaly`, `torzs`, `atlag_suly`, `atlag_eletkor`, `leiras`, `kep`, `kep_mime`, `atlag_meret`, `szerkeszto_id`) VALUES
('szenegali-oroszlan', 'Szenegáli oroszlán', 'Nyugat-Afrika', 'Négylábúak', 'Gerinchúrosok', '140-180 kg', '10-14 év', 'A szenegáli oroszlán (vagy nyugat-afrikai oroszlán) Panthera leo senegalensis (meyeri) az oroszlán egyik alfaja. Az oroszlánok alfajainak megkülönböztetése a méret, a hímek sörénye és az élőhely alapján történik. Ez utóbbira az ad lehetőséget, hogy a populációk meglehetős elszigeteltségben élnek, az oroszlán elterjedése nem folytonos. A különböző élőhelyeken hamar kialakulnak változatok. Törzsalaknak az oroszlánok között a berber oroszlánt tekintik, ehhez képest a szenegáli kisebb testméretű. Sörénye egyszínű, a nyakszirtnél és a nyak felső részén dús, lefelé folytonosan keskenyedik, míg alul hiányzik is.\r\n\r\nA szenegáli oroszlán élőhelye Nyugat-Afrika, Szenegál környéke. A 20. század első felében még az északi szélesség 20°-tól kezdve egészen Afrika déli csücskéig elterjedt, és ezzel a legnagyobb elterjedésű és egyedszámú alfaj volt (A Pallas nagy lexikonának tanúsága szerint). Mára Szenegálban egyetlen szenegáli oroszlán sem maradt, csak a szintén a Szenegál folyó menti gambiai Szenegál Nemzeti Parkban található példányuk.', , 'image/webp', '1,6–2,5 méter', 5);

